  "src/svelte/catalog/compositions/appearance-preview/AppearancePreview.svelte": "<script lang=\"ts\">\n  import { ThemePreview } from \"../../index.ts\";\n  import type { CatalogProps } from \"../../types.d.ts\";\n  // AppearancePreview is ThemePreview (the foundation owns the miniature); this folder stays until Batch 3 prunes it.\n  let { mode, tint, wallpaper }: CatalogProps<\"appearance-preview\"> = $props();\n</script>\n<ThemePreview {mode} {tint} {wallpaper} />\n",
  "src/svelte/catalog/compositions/appearance-preview/appearance-preview.catalog.ts": "// AppearancePreview: a finite miniature of the running interface in one mode, tint and wallpaper, so a person can compare\n// Dark and Light before choosing.\nimport { defineComposition } from \"../../../../authoring/catalog/define.ts\";\nimport { AppearancePreviewContract } from \"./appearance-preview.contract.ts\";\n\nexport const AppearancePreview = defineComposition({\n  id: \"appearance-preview\",\n  purpose: { key: \"appearancePreview.purpose\" }, messages: [\"appearancePreview.purpose\"],\n  owner: { entry: \"AppearancePreview.svelte\" },\n  uses: [\"theme-preview\"], approval: \"none\", contract: AppearancePreviewContract,\n} as const);\n",
  "src/svelte/catalog/compositions/appearance-preview/appearance-preview.contract.ts": "// The props of AppearancePreview: the mode it previews and the tint and wallpaper of the appearance preference it shows\n// (the same values the preference offers).\nimport { Type } from \"@sinclair/typebox\";\n\nexport const AppearancePreviewContract = {\n  props: Type.Object({\n    mode: Type.Union([Type.Literal(\"light\"), Type.Literal(\"dark\")]),\n    tint: Type.Union([Type.Literal(\"blue\"), Type.Literal(\"violet\"), Type.Literal(\"rose\"), Type.Literal(\"green\"), Type.Literal(\"slate\")]),\n    wallpaper: Type.Union([Type.Literal(\"silk\"), Type.Literal(\"mist\"), Type.Literal(\"plain\")]),\n  }, { additionalProperties: false }),\n} as const;\n",
  "src/svelte/catalog/compositions/avatar-shuffle/AvatarShuffle.svelte": "<script lang=\"ts\">\n  import { m } from \"../../../../messages/keys.ts\";\n  import { say } from \"../../../infra/messages.ts\";\n  import { Avatar } from \"../../index.ts\";\n  import type { CatalogProps } from \"../../types.d.ts\";\n  // AvatarShuffle is Avatar with the shuffle interaction (the foundation owns the button and its overlay); this folder\n  // stays until Batch 3 prunes it.\n  let { seed, onchange, disabled = false }: CatalogProps<\"avatar-shuffle\"> = $props();\n</script>\n<Avatar size=\"portrait\" interaction=\"shuffle\" source={{ kind: \"seed\", seed }} shuffleLabel={say(m.avatarShuffle.shuffleAvatar)} {disabled}\n  onshuffle={value => onchange?.(value)} />\n",
  "src/svelte/catalog/compositions/avatar-shuffle/avatar-shuffle.catalog.ts": "// AvatarShuffle: the avatar of a new identity as a button that draws a new seed.\nimport { defineComposition } from \"../../../../authoring/catalog/define.ts\";\nimport { AvatarShuffleContract } from \"./avatar-shuffle.contract.ts\";\n\nexport const AvatarShuffle = defineComposition({\n  id: \"avatar-shuffle\",\n  purpose: { key: \"avatarShuffle.purpose\" }, messages: [\"avatarShuffle.purpose\", \"avatarShuffle.shuffleAvatar\"],\n  owner: { entry: \"AvatarShuffle.svelte\" },\n  uses: [\"avatar\"], approval: \"none\", contract: AvatarShuffleContract,\n} as const);\n",
